import { useEffect, useState } from 'react';
import { analyzeExternalClientReport, getPendingExternalReportAnalyses, saveExternalReportBiomarkers } from '../../lib/externalTransientReportApi';

const stages=['Reading report','Extracting biomarkers','Mapping results','Preparing review'];
const display=(value)=>value===null||value===undefined||value===''?'—':String(value);

export default function ExternalTransientReportAnalyzer({clientId,onSaved,onError}){
  const [open,setOpen]=useState(false);const [file,setFile]=useState(null);const [busy,setBusy]=useState(false);const [stage,setStage]=useState(0);const [analysis,setAnalysis]=useState(null);const [items,setItems]=useState([]);const [notice,setNotice]=useState('');const [dialogError,setDialogError]=useState('');
  useEffect(()=>{let active=true;getPendingExternalReportAnalyses(clientId).then(result=>{const pending=result.analyses?.[0];if(!active||!pending)return;setAnalysis(pending);setItems(pending.items.map(item=>({...item,decision:'PENDING',correction:null})));setOpen(true);}).catch(()=>undefined);return()=>{active=false;};},[clientId]);
  useEffect(()=>{if(!busy)return undefined;const timer=window.setInterval(()=>setStage(value=>Math.min(value+1,stages.length-1)),900);return()=>window.clearInterval(timer);},[busy]);
  const analyze=async(event)=>{event.preventDefault();setBusy(true);setStage(0);setNotice('');setDialogError('');onError('');try{const result=await analyzeExternalClientReport(clientId,file);setAnalysis(result);setItems(result.items.map(item=>({...item,decision:'PENDING',correction:null})));}catch(error){setDialogError(error.message||'We could not read this report. Try a clearer PDF or image.');}finally{setBusy(false);}};
  const updateDecision=(index,decision)=>setItems(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,decision}:item));
  const updateCorrection=(index,key,value)=>setItems(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,decision:'CORRECTED',correction:{...(item.correction||{}),[key]:value}}:item));
  const reviewedCount=items.filter(item=>item.decision!=='PENDING').length;
  const reviewComplete=items.length>0&&reviewedCount===items.length;
  const correctionIncomplete=items.some(item=>item.decision==='CORRECTED'&&!item.correction?.reason?.trim());
  const persistItems=async(nextItems)=>{setBusy(true);setDialogError('');onError('');try{const result=await saveExternalReportBiomarkers(clientId,analysis.analysisId,analysis.reviewToken,nextItems);setNotice(`${result?.savedCount??nextItems.filter(item=>item.decision!=='REJECTED').length} biomarkers saved to the client profile. The source file was not retained.`);setAnalysis(null);setItems([]);setFile(null);setOpen(false);await onSaved();}catch(error){setDialogError(error.message||'Unable to save reviewed biomarkers.');}finally{setBusy(false);}};
  const save=async()=>{if(!reviewComplete||correctionIncomplete)return;await persistItems(items);};
  const confirmAllAndSave=async()=>{if(!items.length||correctionIncomplete)return;const nextItems=items.map(item=>item.decision==='PENDING'?{...item,decision:'CONFIRMED',correction:null}:item);setItems(nextItems);await persistItems(nextItems);};
  return <>
    <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h3 className="font-semibold">Analyze a lab report</h3><p className="mt-1 text-sm text-slate-500">PDF, JPEG, or PNG · up to 12 MB. The file is analyzed transiently and is not stored.</p></div><button onClick={()=>setOpen(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white">Select report</button></div>{notice&&<p role="status" className="mt-4 rounded-xl bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-800">{notice}</p>}</section>
    {open&&<div className="fixed inset-0 z-50 flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4" role="dialog" aria-modal="true" aria-labelledby="report-analysis-title"><section className="max-h-[94dvh] w-full overflow-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:max-w-3xl sm:rounded-2xl sm:p-6"><div className="flex items-start justify-between gap-3"><div><h3 id="report-analysis-title" className="text-xl font-semibold">Analyze lab report</h3><p className="mt-1 text-sm text-slate-500">Review every extracted value before saving it to the client profile.</p></div><button disabled={busy} onClick={()=>{setOpen(false);setAnalysis(null);setItems([]);setDialogError('');}} className="min-h-11 rounded-xl border px-4 text-sm font-semibold">Close</button></div>
      {dialogError&&<div role="alert" className="mt-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-800"><strong className="block">Biomarkers were not saved</strong><span>{dialogError}</span></div>}
      {!analysis&&<form onSubmit={analyze} className="mt-6 space-y-5"><label className="block rounded-2xl border-2 border-dashed border-slate-300 bg-slate-50 p-5 text-sm font-semibold">Choose PDF, JPEG, or PNG<input required disabled={busy} type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" onChange={event=>setFile(event.target.files?.[0]||null)} className="mt-3 block w-full font-normal"/>{file&&<span className="mt-3 block text-xs text-emerald-700">{file.name} · {(file.size/1024/1024).toFixed(2)} MB</span>}</label>{busy?<div role="status" aria-live="polite" className="rounded-2xl bg-blue-50 p-5"><p className="font-semibold text-blue-950">{stages[stage]}</p><div className="mt-3 h-2 overflow-hidden rounded-full bg-blue-100"><div className="h-full bg-blue-600 transition-all" style={{width:`${((stage+1)/stages.length)*100}%`}}/></div><p className="mt-3 text-xs text-blue-800">Larger reports can take a little longer. Keep this window open.</p></div>:<button disabled={!file} className="min-h-11 w-full rounded-xl bg-blue-600 px-5 text-sm font-semibold text-white disabled:opacity-40">Analyze report</button>}</form>}
      {analysis&&<div className="mt-6"><div className="rounded-xl bg-slate-50 p-4 text-sm"><strong>{analysis.sourceFilename}</strong><span className="ml-2 text-slate-500">{items.length} result{items.length===1?'':'s'} found · source file not retained</span><p className="mt-2 font-semibold text-slate-800">{reviewedCount} of {items.length} markers reviewed</p></div><div className="mt-4 space-y-3">{items.map((item,index)=><article key={item.rowIdentity} className={`rounded-2xl border p-4 ${item.decision==='REJECTED'?'border-red-200 bg-red-50':item.decision==='CONFIRMED'?'border-emerald-200 bg-emerald-50/40':item.decision==='CORRECTED'?'border-amber-200 bg-amber-50/40':'border-slate-200'}`}><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><h4 className="font-semibold">{item.canonicalName||item.rawName}</h4><p className="mt-1 text-sm text-slate-600">{display(item.numericValue??item.rawValue)} {item.canonicalUnit||item.rawUnit||''} · {item.observationDate}</p><p className="mt-1 text-xs text-slate-500">Raw: {item.rawName} · Reference: {item.referenceText||'not provided'}</p></div><div className="flex flex-wrap items-center gap-2"><button type="button" aria-pressed={item.decision==='CONFIRMED'} onClick={()=>updateDecision(index,'CONFIRMED')} className={`min-h-11 rounded-lg px-3 text-xs font-semibold ${item.decision==='CONFIRMED'?'bg-emerald-600 text-white':'border border-emerald-300 text-emerald-800'}`}>{item.decision==='CONFIRMED'?'✓ Confirmed':'Confirm marker'}</button><button type="button" aria-pressed={item.decision==='CORRECTED'} onClick={()=>updateDecision(index,'CORRECTED')} className={`min-h-11 rounded-lg px-3 text-xs font-semibold ${item.decision==='CORRECTED'?'bg-amber-500 text-white':'border'}`}>Correct</button><button type="button" aria-pressed={item.decision==='REJECTED'} onClick={()=>updateDecision(index,'REJECTED')} className={`min-h-11 rounded-lg px-3 text-xs font-semibold ${item.decision==='REJECTED'?'bg-red-600 text-white':'border border-red-200 text-red-700'}`}>Reject</button></div></div>{item.decision==='CORRECTED'&&<div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Corrected value<input type="number" step="any" value={item.correction?.value??item.numericValue??''} onChange={event=>updateCorrection(index,'value',event.target.value===''?null:Number(event.target.value))} className="mt-1 w-full rounded-xl border bg-white p-3 text-sm"/></label><label className="text-xs font-semibold">Corrected unit<input value={item.correction?.unit??item.canonicalUnit??item.rawUnit??''} onChange={event=>updateCorrection(index,'unit',event.target.value)} className="mt-1 w-full rounded-xl border bg-white p-3 text-sm"/></label><label className="text-xs font-semibold sm:col-span-2">Reason<input required value={item.correction?.reason??''} onChange={event=>updateCorrection(index,'reason',event.target.value)} className="mt-1 w-full rounded-xl border bg-white p-3 text-sm"/></label></div>}</article>)}</div><div className="sticky bottom-0 mt-5 border-t bg-white py-4"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-medium text-slate-600">{reviewComplete?'All markers reviewed. Save them to the client Biomarkers tab.':`${items.length-reviewedCount} marker${items.length-reviewedCount===1?'':'s'} will be confirmed when you save.`}</p><p className="mt-1 text-xs text-slate-500">Corrections and rejections already made will be preserved.</p></div><div className="flex flex-col gap-2 sm:flex-row"><button disabled={busy} onClick={()=>{setAnalysis(null);setItems([]);setDialogError('');}} className="min-h-11 rounded-xl border px-4 text-sm font-semibold">Choose another report</button><button disabled={busy||!reviewComplete||correctionIncomplete} onClick={save} className="min-h-11 rounded-xl border border-blue-600 px-5 text-sm font-semibold text-blue-700 disabled:cursor-not-allowed disabled:opacity-40">Save reviewed only</button><button disabled={busy||!items.length||correctionIncomplete} onClick={confirmAllAndSave} className="min-h-11 rounded-xl bg-blue-600 px-5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40">{busy?'Saving biomarkers…':'Confirm all & save'}</button></div></div></div></div>}
    </section></div>}
  </>;
}
